        print(' '.join(map(str, connected_vertices)))
    else:
        print()

# Read number of vertices
N = int(input())

# Read adjacency matrix
adjacency = []
for _ in range(N):
    row = list(map(int, input().split()))
    adjacency.append(row)

# For each vertex i (0-indexed), find connected vertices
for i in range(N):
    connected_vertices = []
    # Check each vertex j that could be connected to i
    for j in range(N):
        if adjacency[i][j] == 1:
            # j+1 because vertices are 1-indexed
            connected_vertices.append(j + 1)

    # Print connected vertices in ascending order
    if connected_vertices:
        print(' '.join(map(str, connected_vertices)))
    else:
        print()
